# 7. Optional verification and cleanup
if RUN_WRITE_TEST and test_key:
    head_response = s3.head_object(Bucket=BUCKET_NAME, Key=test_key)
    print("HeadObject succeeded")
    print("ContentLength:", head_response["ContentLength"])

    if RUN_DELETE_AFTER_WRITE_TEST:
        s3.delete_object(Bucket=BUCKET_NAME, Key=test_key)
        print("DeleteObject succeeded")
    else:
        print("Skipping delete because RUN_DELETE_AFTER_WRITE_TEST is False")
else:
    print("Skipping verification and cleanup because write test did not run")
